<?php use MeatinOS\Core\Csrf; ?>
<div class="module-toolbar card-panel"><div><p class="eyebrow">HR & Payroll</p><h2>Payroll Processing</h2><p>Attendance, extra duty, benefits, commissions, advances, deductions, approvals, and ledger posting.</p></div><?php if ($canManage): ?><button class="btn btn-danger" data-bs-toggle="modal" data-bs-target="#payrollModal"><i class="bi bi-calculator me-1"></i>Generate payroll</button><?php endif; ?></div>
