    <div class="col-xl-8"><article class="card-panel table-panel h-100"><div class="panel-heading p-3 mb-0"><div><h2>Employee Pay Register</h2><p>Calculated pay lines for the selected run</p></div><?php if ($canManage && $selectedRun): ?><div class="d-flex gap-2 flex-wrap"><?php if ($selectedRun['status'] === 'draft'): ?><form method="post" action="<?= e(url('payroll.status')) ?>"><?= Csrf::field() ?><input type="hidden" name="run_id" value="<?= e($selectedRun['id']) ?>"><button class="btn btn-sm btn-outline-secondary" name="action" value="cancel" type="submit">Cancel run</button><button class="btn btn-sm btn-success" name="action" value="approve" type="submit"><i class="bi bi-check2-circle me-1"></i>Approve</button></form><?php elseif ($selectedRun['status'] === 'approved'): ?><form method="post" action="<?= e(url('payroll.status')) ?>"><?= Csrf::field() ?><input type="hidden" name="run_id" value="<?= e($selectedRun['id']) ?>"><button class="btn btn-sm btn-success" name="action" value="pay" type="submit"><i class="bi bi-bank me-1"></i>Pay & post ledger</button></form><?php endif; ?></div><?php endif; ?></div><div class="table-responsive"><table class="table data-table"><thead><tr><th>Employee</th><th>Department</th><th>Basic</th><th>OT / extra duty</th><th>Allowances</th><th>Commission</th><th>Advance</th><th>Deductions</th><th>Net pay</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><strong><?= e($item['employee_number']) ?></strong><small class="d-block text-secondary"><?= e($item['full_name']) ?></small></td><td><?= e($item['department']) ?></td><td><?= e(money($item['basic_amount'])) ?></td><td><?= e(number_format((float)$item['overtime_hours'],2)) ?> h<small class="d-block text-secondary"><?= e(money($item['overtime_amount'])) ?></small></td><td><?= e(money($item['allowances'])) ?></td><td><?= e(money($item['commission_amount'])) ?></td><td><?= e(money($item['advance_recovery'])) ?></td><td><?= e(money($item['deductions'])) ?><small class="d-block text-secondary" title="<?= e($item['remarks'] ?? '') ?>">View breakdown</small></td><td><strong><?= e(money($item['net_amount'])) ?></strong></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="9"><div class="table-empty"><i class="bi bi-receipt"></i><strong>No pay lines</strong><span>Select or generate a payroll run.</span></div></td></tr><?php endif; ?></tbody></table></div></article></div>
</div>
<?php if($canManage): ?><div class="modal fade" id="payrollModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-scrollable"><form class="modal-content" method="post" action="<?= e(url('payroll.generate')) ?>"><?= Csrf::field() ?><div class="modal-header"><div><p class="eyebrow mb-1">New pay period</p><h2 class="modal-title fs-4">Generate payroll</h2></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-6"><label class="form-label">Period start</label><input class="form-control" type="date" name="period_start" value="<?= e(date('Y-m-01')) ?>" required></div><div class="col-6"><label class="form-label">Period end</label><input class="form-control" type="date" name="period_end" value="<?= e(date('Y-m-t')) ?>" required></div><div class="col-12"><label class="form-label">Pay date</label><input class="form-control" type="date" name="pay_date" value="<?= e(date('Y-m-t')) ?>" required></div><div class="col-12"><div class="alert alert-info mb-0">The draft calculates basic pay, biometric/manual overtime, extra duty, active benefits, approved target commission, salary-advance recovery, absences, and deductions. Payment requires an active company bank/cash account and posts the ledger atomically.</div></div></div></div><div class="modal-footer"><button class="btn btn-light border" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-danger" type="submit">Generate draft payroll</button></div></form></div></div><?php endif; ?>
